from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 135)
Flipper = Motor(Port.C, Direction.COUNTERCLOCKWISE)
WheelDiameter_mm = 0
WheelCircumference_cm = 0
RotationSpeed = 0
RotateDirection = 0
K = 0
Error = 0

async def Move_2_________cm_at_____Move_speed_at_____Heading(ForwardOrBackward, Distance_cm, MoveSpeed, Heading):
    await wait(0)
    await Move________at_____at____(ForwardOrBackward, (Distance_cm / WheelCircumference_cm) * 360, MoveSpeed, Heading)

async def Move________at_____at____(ForwardOrBackward, RelativePosition, MoveSpeed, Heading):
    global K, RotateDirection, Error
    await wait(0)
    K = 0.5
    if 'forward' in ForwardOrBackward:
        RotateDirection = 1
    else:
        RotateDirection = -1
    while not (abs(0) > abs(RelativePosition) or abs(0) == abs(RelativePosition)):
        await wait(0)
        Error = prime_hub.imu.heading() - Heading
        drive_base.drive((RotateDirection * MoveSpeed - Error * K) * 360, 0)
    drive_base.brake()
    await wait(2000)

async def Initialization():
    await wait(0)
    prime_hub.imu.reset_heading(0)
    drive_base.settings(straight_speed=100)
    await SetWheelProperties()

async def SetWheelProperties():
    global WheelDiameter_mm, WheelCircumference_cm
    await wait(0)
    WheelDiameter_mm = 66
    WheelCircumference_cm = (WheelDiameter_mm / 10) * 3.141592658539

async def Rotate_____to_____degrees(Left_Right, Heading):
    global RotationSpeed, RotateDirection
    await wait(0)
    RotationSpeed = 25
    if 'Left' in Left_Right:
        RotateDirection = -1
    else:
        RotateDirection = 1
    while not abs(prime_hub.imu.heading() - Heading) < 1:
        await wait(0)
        await Left.run_angle((-1 * (RotateDirection * RotationSpeed)) * 360, 360)
        await Right.run_angle((1 * (RotateDirection * RotationSpeed)) * 360, 360)
    Left.brake()
    Right.brake()
    await wait(2000)

async def main1():
    print('Driving Test.')

async def main2():
    await drive_base.straight(1000, then=Stop.BRAKE)

async def main3():
    print('All This Code!')
    await Initialization()
    await Move_2_________cm_at_____Move_speed_at_____Heading('Forward', 10, 10, 10)


async def main():
    await multitask(main1(), main2(), main3())

run_task(main())